@'
import {readFileSync,readdirSync,existsSync} from 'node:fs';
import {resolve,relative,dirname} from 'node:path';
import {parseManifest} from './packages/core/src/domain/manifest.ts';
import {buildSkillPackage} from './packages/core/src/domain/skill-package.ts';
import {validatePackage} from './packages/core/src/application/validate-package.ts';
const root=resolve('skills/java-ddd-aggregates');
const paths=readdirSync(root,{recursive:true,withFileTypes:true}).filter(e=>e.isFile()).map(e=>resolve(e.parentPath,e.name));
const files=paths.map(p=>({path:relative(root,p).replaceAll('\\','/'),bytes:readFileSync(p)}));
const parsed=parseManifest(readFileSync(resolve(root,'skill.yaml'),'utf8'),{strict:true});
const report=validatePackage(buildSkillPackage(parsed.manifest,files),{directoryName:'java-ddd-aggregates'});
const issues=[...parsed.issues,...report.issues];
const links=[];
for(const path of paths.filter(p=>p.endsWith('.md'))) {
 const text=readFileSync(path,'utf8');
 for(const match of text.matchAll(/\[[^\]]*\]\((<[^>]+>|[^\s)]+)(?:\s+[^)]*)?\)/g)) {
  const target=match[1].replace(/^<|>$/g,'');
  if(/^[a-z][a-z0-9+.-]*:/i.test(target)) continue;
  const [file,anchor]=target.split('#');
  const dest=file?resolve(dirname(path),decodeURIComponent(file)):path;
  if(!existsSync(dest)) throw new Error('Missing link '+target+' from '+path);
  if(anchor) {
   const headings=[...readFileSync(dest,'utf8').matchAll(/^#{1,6}\s+(.+)$/gm)].map(m=>m[1].toLowerCase().replace(/[^\w\s-]/g,'').replace(/\s/g,'-'));
   if(!headings.includes(anchor)) throw new Error('Missing anchor '+target);
  }
  links.push({from:relative(root,path).replaceAll('\\','/'),target});
 }
}
console.log(JSON.stringify({skill:'java-ddd-aggregates',files:files.map(f=>f.path),manifestVersion:parsed.manifest.version,issues,relativeLinks:links},null,2));
if(issues.length) process.exitCode=1;
